from fractions import Fraction as F
import json

def text(q):
    if q is None:
        return None
    return str(q)

def value(poly, x):
    a, b = poly
    return a * x + b

def root(poly):
    a, b = poly
    return -b / a if a else None

def analyze(numerator, denominator, require_below_one=False):
    difference = tuple(n - d for n, d in zip(numerator, denominator))
    polynomials = [numerator, denominator]
    if require_below_one:
        polynomials.append(difference)

    boundaries = sorted({r for p in polynomials if (r := root(p)) is not None})

    def admissible(x):
        d = value(denominator, x)
        if d == 0:
            return False
        ratio = value(numerator, x) / d
        return ratio > 0 and (not require_below_one or ratio < 1)

    # Between roots, all relevant linear expressions have constant signs.
    edges = [None] + boundaries + [None]
    accepted = []
    evidence = []
    for left, right in zip(edges, edges[1:]):
        if left is None:
            sample = right - 1
        elif right is None:
            sample = left + 1
        else:
            sample = (left + right) / 2
        ok = admissible(sample)
        evidence.append({
            "interval": [text(left), text(right)],
            "sample": text(sample),
            "accepted": ok
        })
        if ok:
            accepted.append((left, right))

    admitted_boundaries = [x for x in boundaries if admissible(x)]
    return accepted, admitted_boundaries, evidence

def interval_string(interval):
    left, right = interval
    return "(" + ("-infinity" if left is None else text(left)) + ", " + (
        "infinity" if right is None else text(right)
    ) + ")"

try:
    # (1-x)/(1+x), with coefficients ordered as (slope, constant).
    numerator = (F(-1), F(1))
    denominator = (F(1), F(1))
    domain, domain_points, domain_evidence = analyze(numerator, denominator)

    # The quotient derivative has numerator a*d - c*b.
    a, b = numerator
    c, d = denominator
    derivative_numerator = a * d - c * b

    # Substitute t = 2*x - 1 directly into both linear expressions.
    scale, shift = F(2), F(-1)
    transformed_numerator = (a * scale, a * shift + b)
    transformed_denominator = (c * scale, c * shift + d)
    solution, solution_points, solution_evidence = analyze(
        transformed_numerator, transformed_denominator, True
    )

    if (len(domain) != 1 or domain_points or solution_points
            or derivative_numerator == 0):
        print("UNSUPPORTED")
    else:
        monotonicity = (
            "strictly decreasing" if derivative_numerator < 0
            else "strictly increasing"
        )
        domain_text = interval_string(domain[0])
        solution_text = " union ".join(map(interval_string, solution)) or "empty set"
        print(json.dumps({
            "final_answer": (
                f"(1) Domain: {domain_text}; f is {monotonicity} on "
                f"{domain_text}. (2) x in {solution_text}."
            ),
            "evidence": {
                "domain_sign_tests": domain_evidence,
                "derivative": {
                    "quotient_derivative_numerator": text(derivative_numerator),
                    "formula": "f'(x)=(a*d-c*b)/((1+x)^2*R(x)*ln(10))",
                    "R_positive_on_domain": True
                },
                "substituted_ratio_coefficients": {
                    "numerator": list(map(text, transformed_numerator)),
                    "denominator": list(map(text, transformed_denominator))
                },
                "inequality_equivalence": "lg(R)<0 iff 0<R<1",
                "solution_sign_tests": solution_evidence,
                "admitted_boundary_points": []
            }
        }, separators=(",", ":")))
except Exception:
    print("UNSUPPORTED")
